namespace x3 = boost::spirit::x3;

// Reglas de gramática para Markdown
auto const markdown_rule = x3::rule<struct markdown_rule, std::string>{"markdown"}
    = x3::lit("#") >> x3::alpha >> *x3::alnum >> x3::eol
    | x3::lit("##") >> x3::alpha >> *x3::alnum >> x3::eol
    | x3::lit("###") >> x3::alpha >> *x3::alnum >> x3::eol
    | x3::lit("####") >> x3::alpha >> *x3::alnum >> x3::eol
    | x3::lit("#####") >> x3::alpha >> *x3::alnum >> x3::eol
    | x3::lit("######") >> x3::alpha >> *x3::alnum >> x3::eol
    | x3::lit("*") >> x3::alpha >> *x3::alnum >> x3::eol
    | x3::lit("1. ") >> *x3::digit >> *x3::alnum >> x3::eol
    | x3::lit("[") >> *x3::print >> *x3::char_[(c == ']')] >> x3::lit("]") >> *x3::char_(" ") >> x3::lit("(") >> *x3::print >> *x3::char_[(c == ')')] >> x3::eol
    | x3::lit("```") >> *x3::print >> x3::lit("```") >> x3::eol
    | x3::lit("<") >> *x3::print >> x3::lit(">") >> x3::eol
    | x3::lit("-") >> *x3::alnum >> x3::eol
    | *x3::print;

// Reglas de gramática para HTML
auto const html_rule = x3::rule<struct html_rule, std::string>{"html"}
    = x3::lit("<h") >> *x3::digit >> *x3::alnum >> x3::lit(">") >> *x3::print >> x3::lit("</") >> x3::attr<4>("h") >> x3::lit(">")
    | x3::lit("<p>") >> *x3::print >> x3::lit("</p>")
    | x3::lit("<ul>") >> *x3::lit("<li>") >> *x3::print >> x3::lit("</li>") >> *x3::lit("</ul>")
    | x3::lit("<a href=") >> *x3::print >> x3::lit(">") >> *x3::print >> x3::lit("</a>")
    | x3::lit("<pre>") >> *x3::print >> x3::lit("</pre>")
    | x3::lit("<code>") >> *x3::print >> x3::lit("</code>")
    | x3::lit("<strong>") >> *x3::print >> x3::lit("</strong>")
    | x3::lit("<em>") >> *x3::print >> x3::lit("</em>")
    | x3::lit("<img src=") >> *x3::print >> x3::lit(">");

// Función de conversión de Markdown a HTML
std::string convert_to_html(const std::string& markdown) {
    std::string html;
    auto f = markdown.begin();
    auto l = markdown.end();

    if (!x3::parse(f, l, markdown_rule, html)) {
        std::cerr << "Error: fallo en la conversión de Markdown a HTML." << std::endl;
        return "";
    }

    return html;
}

int main() {
