int main() {
    int n, m;
    cout << "Ingrese el número de filas de la primera matriz: ";
    cin >> n;
    cout << "Ingrese el número de columnas de la primera matriz: ";
    cin >> m;

    int arr1[n][m];
    cout << "Ingrese los elementos de la primera matriz:\n";
    for (int I = 0; I < n; i++) {
        for (int j = 0; j < m; j++) {
            cin >> arr1[i][j];
        }
    }

    cout << "Ingrese el número de filas de la segunda matriz: ";
    cin >> n;
    cout << "Ingrese el número de columnas de la segunda matriz: ";
    cin >> m;

    int arr2[n][m];
    cout << "Ingrese los elementos de la segunda matriz:\n";
    for (int I = 0; I < n; i++) {
        for (int j = 0; j < m; j++) {
            cin >> arr2[i][j];
        }
    }

    // Comprobar que las matrices tienen el mismo tamaño
    if (n != m) {
        cout << "Las matrices deben tener el mismo tamaño.\n";
        return 0;
    }

    // Comprobar los elementos comunes
    vector<int> common;
    for (int I = 0; I < n; i++) {
        for (int j = 0; j < m; j++) {
            if (arr1[i][j] == arr2[i][j]) {
                common.push_back(arr1[i][j]);
            }
        }
    }

    // Imprimir los elementos comunes
    if (common.empty()) {
        cout << "No hay elementos comunes en las matrices.\n";
    } else {
